import csv
import json

INPUT_FILE = 'data.csv'
OUTPUT_FILE = 'summary.json'


def parse_number(raw):
    raw = raw.strip()
    try:
        return int(raw)
    except ValueError:
        return float(raw)


def load_values(path):
    values = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            raw = (row.get('value') or '').strip()
            if raw:
                values.append(parse_number(raw))
    return values


def build_summary(values):
    total = sum(values)
    average = total / len(values) if values else 0
    if isinstance(average, float) and average.is_integer():
        average = int(average)
    return {'rows': len(values), 'average': average}


def main():
    values = load_values(INPUT_FILE)
    summary = build_summary(values)
    with open(OUTPUT_FILE, 'w') as f:
        json.dump(summary, f)
    print(json.dumps(summary))


if __name__ == '__main__':
    main()

